<?php namespace App\Policies; use App\Models\{User,Appointment}; class AppointmentPolicy { public function view(User $u,Appointment $a):bool{return $u->role==='admin'||$a->pet->owner_id===$u->id||($u->role==='vet'&&$a->vet->user_id===$u->id);} public function update(User $u,Appointment $a):bool{return $this->view($u,$a);} public function delete(User $u,Appointment $a):bool{return $this->view($u,$a);} }